package com.bank.msgsize.model;

// The three coordinated caps. Default ~1 MB everywhere.
public class SizeLimits {
    public static final int DEFAULT = 1_048_576; // ~1 MB

    private final int maxRequestSize;       // producer
    private final int messageMaxBytes;      // broker / max.message.bytes
    private final int maxPartitionFetchBytes; // consumer (old: fetch.message.max.bytes)

    public SizeLimits(int maxRequestSize, int messageMaxBytes, int maxPartitionFetchBytes) {
        this.maxRequestSize = maxRequestSize;
        this.messageMaxBytes = messageMaxBytes;
        this.maxPartitionFetchBytes = maxPartitionFetchBytes;
    }

    public static SizeLimits defaults() { return new SizeLimits(DEFAULT, DEFAULT, DEFAULT); }

    public int getMaxRequestSize() { return maxRequestSize; }
    public int getMessageMaxBytes() { return messageMaxBytes; }
    public int getMaxPartitionFetchBytes() { return maxPartitionFetchBytes; }
}
