package com.bank.msgsize.pipeline;

import com.bank.msgsize.model.Message;
import com.bank.msgsize.model.SizeLimits;
import java.util.logging.*;

// Enforces the size at each layer IN ORDER: producer, broker, consumer.
public class MessagePipeline {
    private static final Logger log = Logger.getLogger(MessagePipeline.class.getName());
    private final SizeLimits limits;

    public MessagePipeline(SizeLimits limits) { this.limits = limits; }

    public boolean deliver(Message m) {
        // 1) producer check: max.request.size
        if (m.getSizeBytes() > limits.getMaxRequestSize()) {
            log.severe(m + " rejected at PRODUCER (max.request.size="
                + limits.getMaxRequestSize() + ")");
            return false;
        }
        // 2) broker check: message.max.bytes / max.message.bytes
        if (m.getSizeBytes() > limits.getMessageMaxBytes()) {
            log.severe(m + " rejected at BROKER (message.max.bytes="
                + limits.getMessageMaxBytes() + ") — RecordTooLargeException");
            return false;
        }
        // 3) consumer check: max.partition.fetch.bytes
        if (m.getSizeBytes() > limits.getMaxPartitionFetchBytes()) {
            log.severe(m + " stored but UNREADABLE at CONSUMER (max.partition.fetch.bytes="
                + limits.getMaxPartitionFetchBytes() + ") — partition stalls");
            return false;
        }
        log.info(() -> m + " delivered end-to-end (passed producer, broker, consumer)");
        return true;
    }
}
