package com.bank.msgsize.pipeline;

import com.bank.msgsize.model.Message;
import java.util.logging.*;

// Preferred pattern: store big blob externally, publish a tiny reference.
public class ClaimCheck {
    private static final Logger log = Logger.getLogger(ClaimCheck.class.getName());

    // Returns a small reference message instead of the big payload.
    public Message store(String id, int bigPayloadBytes) {
        String s3Key = "s3://bank-statements/" + id + ".pdf";
        log.info("Stored " + bigPayloadBytes + " bytes at " + s3Key);
        // reference message is tiny: just the key + metadata
        int refSize = s3Key.length() + 40;
        return new Message(id + "-ref", refSize);
    }
}
