package com.bank.msgsize;

import com.bank.msgsize.model.Message;
import com.bank.msgsize.model.SizeLimits;
import com.bank.msgsize.pipeline.ClaimCheck;
import com.bank.msgsize.pipeline.MessagePipeline;
import java.util.logging.*;

public class MsgSizeDemo {
    private static final Logger log = Logger.getLogger(MsgSizeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Default ~1 MB limits everywhere.
        MessagePipeline defaults = new MessagePipeline(SizeLimits.defaults());

        log.info("--- small transfer event under defaults ---");
        defaults.deliver(new Message("transfer-event", 2_048)); // 2 KB, fine

        log.info("--- 5 MB statement PDF under DEFAULT limits ---");
        defaults.deliver(new Message("statement-pdf", 5_242_880)); // rejected at producer

        // Raise ALL THREE layers to 5 MB.
        log.info("--- same 5 MB PDF after raising ALL THREE limits ---");
        MessagePipeline raised = new MessagePipeline(
            new SizeLimits(5_242_880, 5_242_880, 5_242_880));
        raised.deliver(new Message("statement-pdf", 5_242_880)); // now delivered

        // Demonstrate the mismatch: broker+producer raised, consumer left at 1 MB.
        log.info("--- mismatch: producer+broker raised, consumer still 1 MB ---");
        MessagePipeline mismatch = new MessagePipeline(
            new SizeLimits(5_242_880, 5_242_880, SizeLimits.DEFAULT));
        mismatch.deliver(new Message("statement-pdf", 5_242_880)); // unreadable at consumer

        // Preferred: claim-check pattern keeps the Kafka message tiny.
        log.info("--- preferred: claim-check (reference only) ---");
        ClaimCheck claimCheck = new ClaimCheck();
        Message ref = claimCheck.store("statement-2026-10-24", 5_242_880);
        defaults.deliver(ref); // tiny reference passes default limits easily
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
